-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        customer_external_id,
        segment,
        effective_from,
        record_source,
        load_datetime,
        violation_00,
        violation_01
    from {{ ref("reference__customer_segment__checked") }}
),
violations as (
    select
        'customer_external_id_not_null' as rule_name,
        customer_external_id,
        segment,
        effective_from,
        record_source,
        load_datetime
    from quarantined
    where violation_00

    union all

    select
        'segment_not_null' as rule_name,
        customer_external_id,
        segment,
        effective_from,
        record_source,
        load_datetime
    from quarantined
    where violation_01
)

select
    rule_name,
    customer_external_id,
    segment,
    effective_from,
    record_source,
    load_datetime
from violations
